SELECT toJSONString(groupArray(tuple(t,hostname,timestamps,log_samples,memory_byte_samples,min_memory_bytes,max_memory_bytes,max_samples_per_second,first,last))) AS payload FROM (SELECT toUnixTimestamp(toStartOfInterval(event_time,INTERVAL 5 MINUTE)) AS t,hostname,count() AS timestamps,sum(second_samples) AS log_samples,sum(metric) AS memory_byte_samples,min(metric) AS min_memory_bytes,max(metric) AS max_memory_bytes,max(second_samples) AS max_samples_per_second,min(event_time) AS first,max(event_time) AS last FROM (SELECT event_time,hostname,avg(CurrentMetric_MemoryTracking) AS metric,count() AS second_samples FROM clusterAllReplicas(default,merge('system','^metric_log')) WHERE event_date BETWEEN '2026-08-08' AND '2026-08-09' AND event_time>=toDateTime('2026-08-08 06:55:56','UTC') AND event_time<toDateTime('2026-08-09 19:40:58','UTC') GROUP BY event_time,hostname) GROUP BY t,hostname ORDER BY t,hostname LIMIT 1000) LIMIT 1 SETTINGS max_threads=2,max_execution_time=30,timeout_before_checking_execution_speed=0,max_rows_to_read=1000000,skip_unavailable_shards=0;
